from __future__ import annotations

from typing import Any, Iterable

from ._models import CanonicalTool


def load_canonical_tools(raw_tools: Iterable[dict[str, Any]]) -> list[CanonicalTool]:
    """Normalizza la lista `tools` arrivata via gRPC in `CanonicalTool`.

    Forma attesa di `raw_tools` (cfr. `AGENT_TOOLS_JSON`):
        {"name": "...", "description": "...", "input_schema": {...}}

    Robusto a:
    - `description` mancante (default `""`).
    - `input_schema` mancante (default `{"type": "object", "properties": {}}`).
    - voci senza `name` (ignorate).
    """
    out: list[CanonicalTool] = []
    for t in raw_tools or ():
        if not isinstance(t, dict):
            continue
        name = (t.get("name") or "").strip()
        if not name:
            continue
        description = t.get("description") or ""
        if not isinstance(description, str):
            description = str(description)
        schema = t.get("input_schema") or t.get("parameters") or {"type": "object", "properties": {}}
        if not isinstance(schema, dict):
            schema = {"type": "object", "properties": {}}
        category = _infer_category(name)
        out.append(CanonicalTool(
            name=name,
            description=description,
            input_schema=schema,
            category=category,
        ))
    return out


def build_lookup(tools: list[CanonicalTool]) -> dict[str, CanonicalTool]:
    """Ritorna mappa `name -> CanonicalTool` per O(1) lookup nel validator."""
    return {t.name: t for t in tools}


def _infer_category(name: str) -> str | None:
    """Categoria euristica per audit/log (non altera comportamento).

    Allineata a `docs/.nexus-vault/api/tool-catalog.md`.
    """
    if name.startswith("git_"):
        return "git"
    if name.startswith("knowledge_"):
        return "knowledge"
    if name.startswith("dispatcher_"):
        return "dispatcher"
    if name.startswith("dispatch_subagent") or name.startswith("nexus_subagent_"):
        return "subagent"
    if name.startswith("fs_") or name.startswith("nexus_tools.fs_"):
        return "fs"
    if name in {"read_file", "read_file_lines", "write_file", "edit_file", "list_files",
                "search_in_files", "delete_file", "rename_file", "format_file",
                "run_lint_fix", "run_specific_test"}:
        return "fs"
    if name in {"run_command", "run_tests", "run_playwright_tests"}:
        return "shell"
    if name in {"run_service", "read_service_output", "stop_service", "service_restart",
                "tail_service_logs", "list_active_services", "build_project_image"}:
        return "service"
    if name in {"set_sandbox_config", "get_sandbox_config", "request_port"}:
